script:
(function () {
  'use strict';
  // Personal loan with an origination fee. Monthly payments; the interest rate compounds monthly (i = r/12).
  //   Fee F = amount * fee% (or a dollar amount). Balance repaid B and cash in hand C:
  //     deducted from the proceeds: B = amount, C = amount - F
  //     paid upfront in cash:       B = amount, C = amount - F (you hand the fee back)
  //     added to the balance:       B = amount + F, C = amount
  //   Payment = B * i / (1 - (1 + i)^-n). APR (actuarial method, as in Reg Z): the monthly rate j that
  //   makes the present value of the n payments equal C, times 12 (found by bisection).
  //   To get a set amount in hand when the fee is deducted: borrow amount / (1 - fee%) or amount + F.
  // Verified in Node (scratchpad w3loans/tests): $20,000 at 10% for 5 years = $424.94/mo, total interest
  //   $5,496.45 (closed form; matches a published calculator's default result); $16,000 at 12% for 5 years
  //   with a 5% fee deducted = $355.91/mo and APR 14.283% (a published worked example gives 14.284%,
  //   within 0.001 point; ours is the exact actuarial root);
  //   no fee gives APR = rate; 0% with a fee gives a positive APR; blank, negative, 0-term input and a fee
  //   of 100% or more show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var rateFmt = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 3 });
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function presentValue(pmt, j, n) {
    if (Math.abs(j) < 1e-12) return pmt * n;
    return pmt * (1 - Math.pow(1 + j, -n)) / j;
  }

  // Monthly rate j with presentValue(pmt, j, n) = cash. Returns NaN when no rate in [0, 100% a month] fits.
  function solveRate(cash, pmt, n) {
    if (cash <= 0 || pmt <= 0) return NaN;
    if (pmt * n <= cash + 1e-9) return pmt * n < cash - 1e-6 ? NaN : 0;
    var lo = 0, hi = 1;
    if (presentValue(pmt, hi, n) > cash) return NaN;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (presentValue(pmt, mid, n) > cash) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function amortize(loan, i, n) {
    var pay = payment(loan, i, n), bal = loan, rows = [], totalInterest = 0;
    for (var k = 1; k <= n; k++) {
      var interest = bal * i, principal = k === n ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: k, interest: interest, principal: principal, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function cell(tr, text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); }

  function headRow(labels) {
    var head = el('plScheduleHead');
    head.textContent = '';
    var tr = document.createElement('tr');
    labels.forEach(function (t) { var th = document.createElement('th'); th.scope = 'col'; th.textContent = t; tr.appendChild(th); });
    head.appendChild(tr);
  }

  function clearResults() {
    ['plPayment', 'plApr', 'plCost', 'plInterest', 'plFeeAmt', 'plCash', 'plBalance', 'plTotal', 'plPayoff'].forEach(function (id) { setText(id, '–'); });
    el('plGross').hidden = true;
    el('plSchedule').textContent = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('plSchedule');
    body.textContent = '';
    if (!last) return;
    if (el('plView').value === 'period') {
      headRow(['Month', 'Payment', 'Principal', 'Interest', 'Balance']);
      last.rows.forEach(function (row) {
        var tr = document.createElement('tr'), d = new Date(last.year, last.month + row.n - 1, 1);
        cell(tr, MONTHS[d.getMonth()] + ' ' + d.getFullYear()); cell(tr, money.format(row.principal + row.interest));
        cell(tr, money.format(row.principal)); cell(tr, money.format(row.interest)); cell(tr, money.format(row.balance));
        body.appendChild(tr);
      });
    } else {
      headRow(['Year', 'Principal', 'Interest', 'Ending balance']);
      var p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        var yr = new Date(last.year, last.month + row.n - 1, 1).getFullYear();
        if (idx === last.rows.length - 1 || new Date(last.year, last.month + row.n, 1).getFullYear() !== yr) {
          var tr = document.createElement('tr');
          cell(tr, String(yr)); cell(tr, money.format(p)); cell(tr, money.format(intr)); cell(tr, money.format(row.balance));
          body.appendChild(tr);
          p = 0; intr = 0;
        }
      });
    }
  }

  function update() {
    var amount = read('plAmount'), rate = read('plRate'), years = read('plYears', true), months = read('plMonths', true),
        feeValue = read('plFee', true), feeUnit = el('plFeeUnit').value, feeHow = el('plFeeHow').value,
        month = parseInt(el('plStartMonth').value, 10), year = read('plStartYear'), msg = '';
    var n = years * 12 + months;
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100%.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || years > 30 || months > 11)
      msg = 'Enter the term as whole years (0 to 30) and months (0 to 11).';
    else if (n < 1) msg = 'Enter a loan term of at least one month.';
    else if (isNaN(feeValue) || feeValue < 0) msg = 'The origination fee cannot be negative.';
    else if (feeUnit === 'pct' && feeValue >= 100) msg = 'Enter an origination fee below 100%.';
    else if (feeUnit === 'usd' && feeHow !== 'added' && feeValue >= amount) msg = 'The origination fee must be less than the loan amount.';
    else if (isNaN(year) || year % 1 !== 0 || year < 1900 || year > 2200) msg = 'Enter the first payment year as a four-digit year.';
    var error = el('plError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var fee = feeUnit === 'pct' ? amount * feeValue / 100 : feeValue;
    var balance = feeHow === 'added' ? amount + fee : amount;
    var cash = feeHow === 'added' ? amount : amount - fee;
    var i = rate / 100 / 12;
    var r = amortize(balance, i, n);
    var j = fee > 0 ? solveRate(cash, r.payment, n) : i;

    setText('plPayment', money.format(r.payment));
    setText('plApr', isNaN(j) ? 'Over 1,200%' : rateFmt.format(j * 12));
    setText('plCost', money.format(r.totalInterest + fee));
    setText('plInterest', money.format(r.totalInterest));
    setText('plFeeAmt', money.format(fee));
    setText('plCash', money.format(cash));
    setText('plBalance', money.format(balance));
    setText('plTotal', money.format(r.payment * n + (feeHow === 'upfront' ? fee : 0)));
    var end = new Date(year, month + n - 1, 1);
    setText('plPayoff', MONTHS[end.getMonth()] + ' ' + end.getFullYear() + ' (' + duration(n) + ')');

    var showGross = feeHow === 'deducted' && fee > 0;
    el('plGross').hidden = !showGross;
    if (showGross) {
      var gross = feeUnit === 'pct' ? amount / (1 - feeValue / 100) : amount + fee;
      setText('plGrossText', 'The fee is taken out of the loan, so you receive ' + money.format(cash) + '. To end up with ' +
        money.format(amount) + ' in hand, you would need to borrow about ' + money.format(gross) +
        ', with a monthly payment of ' + money.format(payment(gross, i, n)) + '.');
    }
    last = { rows: r.rows, year: year, month: month };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('plForm');
    if (!form) return;
    var now = new Date(), first = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    el('plStartMonth').value = String(first.getMonth());
    el('plStartYear').value = String(first.getFullYear());
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('plView').addEventListener('change', renderSchedule);
    update();
  });
})();
